def wrap_indent_block(text, width, indent):
    words = text.split()
    lines = []
    line = []
    length = 0
    for w in words:
        extra = len(w) + (1 if line else 0)
        if length + extra <= width:
            line.append(w)
            length += extra
        else:
            lines.append(' '.join(line))
            line = [w]
            length = len(w)
    if line:
        lines.append(' '.join(line))
    pad = ' ' * indent
    return '\n'.join(pad + l for l in lines)

