def total_break_minutes(schedule):
    if len(schedule) < 2:
        return 0
    idle = 0
    for i in range(1, len(schedule)):
        prev_end = schedule[i - 1][1]
        curr_start = schedule[i][0]
        idle += curr_start - prev_end
    return idle

