def meets_strict_password_policy(s):
    if len(s) < 10:
        return False
    if any(c.isspace() for c in s):
        return False
    specials = "!@#$%^&*"
    has_upper = has_lower = has_digit = has_special = False
    for c in s:
        if c.isupper():
            has_upper = True
        elif c.islower():
            has_lower = True
        elif c.isdigit():
            has_digit = True
        if c in specials:
            has_special = True
    return has_upper and has_lower and has_digit and has_special

