        return False
    if s[0] != '#':
        return False
    body = s[1:]
    if len(body) > 30:
        return False
    first = body[0]
    if not first.isalpha():
        return False
    for ch in body:
        if not (ch.isalnum() or ch == '_'):
            return False
    return True

def is_valid_base64_format(s):
    if not s or len(s) % 4 != 0:
        return False
    pad = 0
    i = len(s) - 1
    while i >= 0 and s[i] == '=' and pad < 2:
        pad += 1
        i -= 1
    core = s[:len(s) - pad]
    if '=' in core:
        return False
    allowed = set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/')
    for ch in core:
        if ch not in allowed:
            return False
    return True

